-- CA Tracker central database: PostgreSQL (version 1).
--
-- Plain SQL so it ports to other databases: standard types, identity columns, primary and foreign
-- keys, no stored procedures, triggers or extensions. Every table starts with ca_ so it can live
-- inside an existing database (such as the company workload tracker's) next to its own tables.
-- Other databases: SQL Server - TEXT -> NVARCHAR(MAX), BOOLEAN -> BIT, TIMESTAMP WITH TIME ZONE ->
-- DATETIMEOFFSET, "GENERATED BY DEFAULT AS IDENTITY" -> IDENTITY(1,1); MySQL - TIMESTAMP WITH TIME
-- ZONE -> DATETIME(6) in UTC, TEXT columns used as keys are already VARCHAR here.
--
-- Two kinds of tables:
--   * ca_changes and ca_current carry the sync protocol (central/PROTOCOL.md): every accepted change
--     in order, and the latest version of each project and item.
--   * ca_tracked_projects, ca_discipline_choices, ca_provider_projects, ca_items and ca_item_holders
--     are kept up to date from those changes for reports and other apps (read them; don't write them).
--
-- Safe to run again: everything is CREATE ... IF NOT EXISTS.

CREATE TABLE IF NOT EXISTS ca_schema (
    version     INTEGER NOT NULL PRIMARY KEY,
    applied_at  TIMESTAMP WITH TIME ZONE NOT NULL
);

-- Who may use the API. Only a SHA-256 hash of each access token is kept.
CREATE TABLE IF NOT EXISTS ca_tokens (
    token_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    token_hash   VARCHAR(64) NOT NULL UNIQUE,
    person       VARCHAR(200) NOT NULL,            -- who it was issued to (name or email)
    person_ref   VARCHAR(200),                     -- that person's id in another system (e.g. the workload tracker)
    can_write    BOOLEAN NOT NULL DEFAULT TRUE,    -- false: may read everyone's changes but not send any
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked_at   TIMESTAMP WITH TIME ZONE
);

-- Each CA Tracker install (one per Windows user and PC).
CREATE TABLE IF NOT EXISTS ca_clients (
    client_id        VARCHAR(64) PRIMARY KEY,
    token_id         BIGINT REFERENCES ca_tokens (token_id),
    user_name        VARCHAR(200),
    app_version      VARCHAR(40),
    last_client_seq  BIGINT NOT NULL DEFAULT 0,    -- the highest change number accepted from it (retries below it are ignored)
    first_seen_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    last_seen_at     TIMESTAMP WITH TIME ZONE NOT NULL
);

-- Every accepted change, in order. seq is what clients read from ("changes after N").
CREATE TABLE IF NOT EXISTS ca_changes (
    seq           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id     VARCHAR(64) NOT NULL REFERENCES ca_clients (client_id),
    client_seq    BIGINT NOT NULL,
    user_name     VARCHAR(200),
    entity        VARCHAR(20) NOT NULL,
    entity_key    VARCHAR(500) NOT NULL,
    operation     VARCHAR(10) NOT NULL,
    changed_at    TIMESTAMP WITH TIME ZONE NOT NULL,  -- when the PC made or read it
    received_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    payload       TEXT,                               -- the project or item as JSON; null for deletes
    payload_hash  VARCHAR(64),
    CONSTRAINT ca_changes_client_seq UNIQUE (client_id, client_seq),
    CONSTRAINT ca_changes_entity CHECK (entity IN ('project', 'item')),
    CONSTRAINT ca_changes_operation CHECK (operation IN ('insert', 'update', 'delete'))
);
CREATE INDEX IF NOT EXISTS ca_changes_entity_key ON ca_changes (entity, entity_key);

-- The latest version of every project and item: a change identical to it is not stored again.
CREATE TABLE IF NOT EXISTS ca_current (
    entity        VARCHAR(20) NOT NULL,
    entity_key    VARCHAR(500) NOT NULL,
    payload       TEXT,
    payload_hash  VARCHAR(64),
    deleted       BOOLEAN NOT NULL,
    last_seq      BIGINT NOT NULL,
    changed_at    TIMESTAMP WITH TIME ZONE NOT NULL,          -- when that version was made or read (an older read of an item is not stored)
    updated_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    updated_by    VARCHAR(200),
    PRIMARY KEY (entity, entity_key)
);

-- ---- Readable tables (kept up to date by the server) -------------------------------------------

-- Each person's tracker projects. Several people may track the same Helix/Procore project.
CREATE TABLE IF NOT EXISTS ca_tracked_projects (
    project_key            VARCHAR(64) PRIMARY KEY,   -- the tracker project's id
    client_id              VARCHAR(64),
    user_name              VARCHAR(200),
    name                   TEXT NOT NULL,
    ca_folder              TEXT,                      -- on that person's PC
    provider               VARCHAR(20),               -- 'helix' or 'procore'; null when not linked
    provider_project_id    VARCHAR(200),
    provider_project_name  TEXT,
    company_name           TEXT,
    phase                  VARCHAR(40),               -- Whole, BaseBuild or TenantFitOut
    updated_at             TIMESTAMP WITH TIME ZONE NOT NULL,
    deleted_at             TIMESTAMP WITH TIME ZONE   -- removed from that person's list
);
CREATE INDEX IF NOT EXISTS ca_tracked_projects_provider ON ca_tracked_projects (provider, provider_project_id);

-- Which discipline an item, or a CA folder, belongs to (decides the discipline sub-folder).
CREATE TABLE IF NOT EXISTS ca_discipline_choices (
    project_key  VARCHAR(64) NOT NULL REFERENCES ca_tracked_projects (project_key) ON DELETE CASCADE,
    item_type    VARCHAR(20) NOT NULL,     -- 'rfi' or 'submittal'
    target_kind  VARCHAR(10) NOT NULL,     -- 'folder' (a CA folder's name) or 'item' (a Helix/Procore item id)
    target       VARCHAR(500) NOT NULL,
    discipline   VARCHAR(100) NOT NULL,
    PRIMARY KEY (project_key, item_type, target_kind, target)
);

-- Helix and Procore projects seen in tracker projects.
CREATE TABLE IF NOT EXISTS ca_provider_projects (
    provider             VARCHAR(20) NOT NULL,
    provider_project_id  VARCHAR(200) NOT NULL,
    name                 TEXT NOT NULL,
    updated_at           TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (provider, provider_project_id)
);

-- RFIs and Submittals as last read from Helix or Procore by anyone.
CREATE TABLE IF NOT EXISTS ca_items (
    provider             VARCHAR(20) NOT NULL,
    provider_project_id  VARCHAR(200) NOT NULL,
    item_type            VARCHAR(20) NOT NULL,     -- 'rfi' or 'submittal'
    item_id              VARCHAR(200) NOT NULL,
    number               TEXT NOT NULL,
    title                TEXT NOT NULL,
    status               TEXT NOT NULL,
    status_rank          INTEGER,
    closed               BOOLEAN NOT NULL,
    responsible          TEXT NOT NULL,
    contract             TEXT NOT NULL,
    attachment_count     INTEGER NOT NULL,
    created_at           TIMESTAMP WITH TIME ZONE,
    modified_at          TIMESTAMP WITH TIME ZONE,
    due_at               TIMESTAMP WITH TIME ZONE,
    source_url           TEXT,
    read_at              TIMESTAMP WITH TIME ZONE NOT NULL,   -- when it was read from Helix/Procore
    read_by              VARCHAR(200),
    deleted_at           TIMESTAMP WITH TIME ZONE,            -- no longer in Helix/Procore
    PRIMARY KEY (provider, provider_project_id, item_type, item_id)
);

-- Whose court an item is in: 'current' holders have it now; others are 'upcoming' or done.
CREATE TABLE IF NOT EXISTS ca_item_holders (
    provider             VARCHAR(20) NOT NULL,
    provider_project_id  VARCHAR(200) NOT NULL,
    item_type            VARCHAR(20) NOT NULL,
    item_id              VARCHAR(200) NOT NULL,
    ordinal              INTEGER NOT NULL,
    name                 TEXT NOT NULL,
    company              TEXT,
    state                VARCHAR(20) NOT NULL,
    since                TIMESTAMP WITH TIME ZONE,
    PRIMARY KEY (provider, provider_project_id, item_type, item_id, ordinal),
    FOREIGN KEY (provider, provider_project_id, item_type, item_id)
        REFERENCES ca_items (provider, provider_project_id, item_type, item_id) ON DELETE CASCADE
);

-- Open items and who has them now: one row per current holder.
CREATE OR REPLACE VIEW ca_items_in_court AS
SELECT i.provider,
       i.provider_project_id,
       p.name AS project_name,
       i.item_type,
       i.item_id,
       i.number,
       i.title,
       i.status,
       i.due_at,
       h.name AS holder,
       h.company AS holder_company,
       h.since AS holder_since,
       i.read_at
FROM ca_items i
JOIN ca_item_holders h
  ON h.provider = i.provider AND h.provider_project_id = i.provider_project_id
 AND h.item_type = i.item_type AND h.item_id = i.item_id AND h.state = 'current'
LEFT JOIN ca_provider_projects p
  ON p.provider = i.provider AND p.provider_project_id = i.provider_project_id
WHERE i.deleted_at IS NULL AND i.closed = FALSE;

INSERT INTO ca_schema (version, applied_at)
SELECT 1, CURRENT_TIMESTAMP
WHERE NOT EXISTS (SELECT 1 FROM ca_schema WHERE version = 1);
